export class Person {
  readonly #courses: Course[] = [];

  get courses(): readonly Course[] {
    return this.#courses;             // type-level read-only; `[...]` for runtime copies
  }

  addCourse(course: Course): void {
    if (!course.accepted) throw new Error('course not accepted');
    this.#courses.push(course);
  }
}
